// Cloudflare entry point. Everything normal is the Next.js app built by OpenNext; the one addition
// is the cron trigger (wrangler.jsonc "triggers"): every few hours it calls the app's own
// /api/sync route through the WORKER_SELF_REFERENCE binding, so the sync engine runs with the
// same code, database and settings as the website. No human, no external scheduler.
//
// This file is only used on Cloudflare (`npm run cf:build`, Linux or WSL); it is not type-checked
// by `npm run typecheck` because .open-next/ does not exist until a Cloudflare build.
// @ts-expect-error generated by `opennextjs-cloudflare build`
import openNext from "./.open-next/worker.js";

type Env = { WORKER_SELF_REFERENCE: { fetch: (r: Request) => Promise<Response> }; SYNC_SECRET?: string };

export default {
  fetch: openNext.fetch,

  async scheduled(_controller: unknown, env: Env, ctx: { waitUntil: (p: Promise<unknown>) => void }) {
    if (!env.SYNC_SECRET) {
      console.error("cron sync skipped: SYNC_SECRET is not set (npx wrangler secret put SYNC_SECRET)");
      return;
    }
    ctx.waitUntil(
      env.WORKER_SELF_REFERENCE.fetch(new Request("https://self.internal/api/sync", { method: "POST", headers: { "x-sync-secret": env.SYNC_SECRET } }))
        .then(async (r) => console.log("cron sync:", r.status, (await r.text()).slice(0, 500)))
        .catch((e) => console.error("cron sync failed", e)),
    );
  },
};

// OpenNext's other exports (Durable Objects, if a cache override ever needs them)
export * from "./.open-next/worker.js";
